import java.util.*;

public class Lookup {
    record User(int id, String name) {}
    static final Map<Integer, User> USERS = Map.of(1, new User(1, "Ada"));

    static Optional<User> findUser(int id) {
        return Optional.ofNullable(USERS.get(id));      // no null escapes.
    }

    static String expensiveGuestName() {
        System.out.println("(computing guest)");
        return "guest";
    }

    public static void main(String[] args) {
        String a = findUser(1).map(User::name).orElseGet(Lookup::expensiveGuestName);
        System.out.println(a);                           // Ada (no computing line)
        String b = findUser(9).map(User::name).orElseGet(Lookup::expensiveGuestName);
        System.out.println(b);                           // (computing guest) then guest
    }
}
```

| Use | Avoid |
|---|---|
| Optional return for maybe-missing results. | Optional fields and parameters. |
| map, filter, orElseGet, orElseThrow. | get() without a check. |
| empty collections for "no items". | Optional<List<T>>. |

